function paintTerrain(){if(!heights)return;const lev=Math.round(level()*5)/5,ice=year<-9500;let key=lev+'_'+ice;if(key===terrainKey)return;terrainKey=key;const a=terrainPixels.data,w=land.width;for(let i=0;i<heights.length;i++){let h=heights[i],j=i*4;if(ice){let n=Math.sin((i%w)/110+Math.floor(i/w)/120)*4;a[j]=223+n;a[j+1]=234+n;a[j+2]=233+n}else if(h<=lev){let shore=h>lev-3&&h>0;a[j]=shore?164:184;a[j+1]=shore?199:215;a[j+2]=shore?202:218}else {let dh=h-lev,shade=Math.max(-10,Math.min(10,(h-(heights[i-1]??h))*.8));let beach=dh<2;a[j]=(beach?216:202-Math.min(30,dh*.28))+shade;a[j+1]=(beach?213:211-Math.min(27,dh*.22))+shade;a[j+2]=(beach?171:169-Math.min(29,dh*.24))+shade}a[j+3]=255}lctx.putImageData(terrainPixels,0,0)}
function project(lon,lat){return [(lon+180)/360*meta.world-meta.x0,(1-Math.asinh(Math.tan(lat*Math.PI/180))/Math.PI)/2*meta.world-meta.y0]}
