$('#play').onclick=()=>{if(playing){pause();return}if(pos>=1300)setTime(0);playing=true;$('#play').innerHTML='Ⅱ <span>Pausa</span>';$('#play').setAttribute('aria-label','Pausa tidsresan');lastTick=performance.now();timer=setInterval(()=>{let now=performance.now(),newPos=pos+(now-lastTick)/60;lastTick=now;const stop=(Math.floor(pos/100)+1)*100;if($('#autostop').checked&&newPos>=stop){setTime(stop);pause()}else{setTime(newPos);if(pos>=1300)pause()}},100)};
$('#time').oninput=e=>{pause();setTime(e.target.value)};$('#previous').onclick=()=>{pause();setTime(Math.max(0,Math.ceil(pos/100)-1)*100)};$('#next').onclick=()=>{pause();setTime(Math.min(13,Math.floor(pos/100)+1)*100)};document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{pause();selected=null;setTime(Number(b.dataset.step)*100)});
$('#zoomIn').onclick=()=>zoomAt(1.6);$('#zoomOut').onclick=()=>zoomAt(1/1.6);$('#reset').onclick=()=>{zoom=1;panX=panY=0;draw()};canvas.addEventListener('wheel',e=>{e.preventDefault();const r=canvas.getBoundingClientRect();zoomAt(e.deltaY>0?.88:1.14,e.clientX-r.left,e.clientY-r.top)},{passive:false});
canvas.addEventListener('pointerdown',e=>{canvas.setPointerCapture(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});gesture={x:e.clientX,y:e.clientY,panX,panY};dragged=false;if(pointers.size===2){let [a,b]=[...pointers.values()];gesture={distance:Math.hypot(a.x-b.x,a.y-b.y),zoom};dragged=true}});
canvas.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){let [a,b]=[...pointers.values()],r=canvas.getBoundingClientRect();if(gesture.distance)zoomAt((Math.hypot(a.x-b.x,a.y-b.y)/gesture.distance*gesture.zoom)/zoom,(a.x+b.x)/2-r.left,(a.y+b.y)/2-r.top);return}if(!gesture||gesture.distance)return;let dx=e.clientX-gesture.x,dy=e.clientY-gesture.y;if(Math.abs(dx)+Math.abs(dy)>5)dragged=true;panX=gesture.panX+dx;panY=gesture.panY+dy;draw()});
canvas.addEventListener('pointerup',e=>{if(!dragged&&pointers.size===1){let r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top,h=hits.filter(h=>Math.hypot(x-h.x,y-h.y)<Math.max(22,h.size)).sort((a,b)=>Math.hypot(x-a.x,y-a.y)-Math.hypot(x-b.x,y-b.y))[0];if(h)selectBuilding(h.id,false)}pointers.delete(e.pointerId);gesture=null;if(pointers.size===1){let a=[...pointers.values()][0];gesture={x:a.x,y:a.y,panX,panY};dragged=true}});canvas.addEventListener('pointercancel',()=>{pointers.clear();gesture=null});
canvas.addEventListener('keydown',e=>{if(['+','=','-','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Home'].includes(e.key)){e.preventDefault();if(e.key==='+'||e.key==='=')zoomAt(1.5);if(e.key==='-')zoomAt(1/1.5);if(e.key==='ArrowUp')panY+=50;if(e.key==='ArrowDown')panY-=50;if(e.key==='ArrowLeft')panX+=50;if(e.key==='ArrowRight')panX-=50;if(e.key==='Home'){zoom=1;panX=panY=0}draw()}});
$('#sources').innerHTML=Object.keys(sources).map(k=>`<li>${sourceLink(k)}</li>`).join('');$('#about').onclick=()=>{pause();$('#info').showModal()};$('#closeInfo').onclick=()=>$('#info').close();new ResizeObserver(resize).observe(canvas);document.addEventListener('visibilitychange',()=>{if(document.hidden)pause()});
setTime(600);
(async()=>{try{const res=await fetch('assets/terrain.json');if(!res.ok)throw Error('metadata');meta=await res.json();let im=new Image();im.src='assets/terrain.png';await im.decode();land.width=meta.width;land.height=meta.height;lctx.drawImage(im,0,0);let raw=lctx.getImageData(0,0,land.width,land.height);heights=new Float32Array(raw.data.length/4);for(let i=0;i<heights.length;i++)heights[i]=raw.data[i*4]*256+raw.data[i*4+1]+raw.data[i*4+2]/256-32768;terrainPixels=lctx.createImageData(land.width,land.height);detailTerrain.initialize(meta,heights);$('#mapStatus').textContent='';paintTerrain();resize()}catch(e){$('#mapStatus').textContent='Kartan kunde inte laddas. Ladda om sidan för att försöka igen. Berättelserna går fortfarande att läsa.';console.error(e)}})();
